// T1 Function
// Jeep nominal cold press = 35 deg
// high press alarm = nom + 20%
// low press alarm = nom - 10% (31.5)
// high temp = > 158 deg

var pressure = Math.round(msg.payload["pressure_psi"]);
var temperature = Math.round(msg.payload["temperature_f"]);
var alerts = msg.payload["alerts"];
var color = "green";

if ( pressure < 32 )
    color = "yellow";

if ( alerts == 1 ) // fast leak
    color = "red";

if ( alerts == 2 ) // low batter
    color = "blue";


var msg1 ={};

msg1.payload = [{"command":"update_text","elementId":"T1_pres","textContent":pressure},
                {"command":"update_text","elementId":"T1_temp","textContent":temperature},
                {"command":"set_attribute","selector":"#T1","attributeName":"fill","attributeValue":color}];

return msg1;

